import numpy as np

def make_input(agent, reward, movers, prev_movers, obstacles=()):
    x = np.zeros((10, 10, 5), dtype=np.float32)
    # border walls in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[r, c, 3] = 1.0
    for r, c in obstacles:
        x[r, c, 3] = 1.0
    if agent is not None:
        x[agent[0], agent[1], 0] = 1.0
    for r, c in movers:
        x[r, c, 1] = 1.0
    if reward is not None:
        x[reward[0], reward[1], 2] = 1.0
    prev = set()
    if agent is not None:
        prev.add(agent)
    prev.update(prev_movers)
    for r, c in prev:
        x[r, c, 4] = 1.0
    return x.flatten()

scenarios = [
    ("baseline", (8,4), (1,4), [], []),
    ("mover_above_static", (8,4), (1,4), [(7,4)], [(7,4)]),
    ("mover_above_moving_left", (8,4), (1,4), [(7,4)], [(7,5)]),
    ("mover_above_moving_right", (8,4), (1,4), [(7,4)], [(7,3)]),
    ("mover_two_above", (8,4), (1,4), [(6,4)], [(6,4)]),
    ("agent_higher_mover_above", (5,4), (1,4), [(4,4)], [(4,4)]),
    ("agent_higher_mover_above_left", (5,4), (1,4), [(4,4)], [(4,5)]),
    ("reward_below", (5,4), (8,4), [], []),
    ("reward_below_mover_above", (5,4), (8,4), [(4,4)], [(4,4)]),
]

X = np.stack([make_input(a, r, m, pm) for _, a, r, m, pm in scenarios])
logits = forward(X)
for i, (name, *_ ) in enumerate(scenarios):
    l = logits[i]
    print(f"{name:28s} logits={np.round(l,2)} argmax={int(np.argmax(l))}")
